import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel source for fused ReLU + HardSwish
fused_relu_hardswish_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_relu_hardswish_kernel(const float* __restrict__ in, float* __restrict__ out, int numel) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < numel) {
        float x = in[idx];
        // First apply ReLU
        if (x < 0.0f) {
            x = 0.0f;
        }
        // Then multiply with clamp((x + 3) / 6, 0, 1)
        float c = (x + 3.0f) / 6.0f;
        if (c < 0.0f) {
            c = 0.0f;
        } else if (c > 1.0f) {
            c = 1.0f;
        }
        out[idx] = x * c;
    }
}

torch::Tensor fused_relu_hardswish_cuda(torch::Tensor x) {
    auto output = torch::empty_like(x);
    int numel = x.numel();
    const int block = 256;
    const int grid = (numel + block - 1) / block;
    fused_relu_hardswish_kernel<<<grid, block>>>(x.data_ptr<float>(), output.data_ptr<float>(), numel);
    return output;
}
"""

fused_relu_hardswish_header = r"""
torch::Tensor fused_relu_hardswish_cuda(torch::Tensor x);
"""

# Build the custom extension
fused_relu_hardswish = load_inline(
    name="fused_relu_hardswish",
    cpp_sources=fused_relu_hardswish_header,
    cuda_sources=fused_relu_hardswish_source,
    functions=["fused_relu_hardswish_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that performs a convolution, then fused ReLU + HardSwish in a single custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.fused_relu_hardswish = fused_relu_hardswish

    def forward(self, x):
        x = self.conv(x)
        x = self.fused_relu_hardswish.fused_relu_hardswish_cuda(x)
        return x

